class Base:
    def __init__(self):
        self.__tag = "base"
    def tag(self):
        return self.__tag

class Child(Base):
    def __init__(self):
        super().__init__()
        self.__tag = "child"

print(Child().tag())

class Api:
    def __init__(self):
        self.__key = "s3cr3t"

class Client(Api):
    def show(self):
        return self.__key

print(Client().show())

